For a symmetric channel $W \in \mathcal{P}(\mathcal{Y}\mid \mathcal{X})$, the
{\em information density} is defined as
\begin{equation}
    i(x, y) := \log \frac{W(y\mid x)}{Q(y)}, \quad \text{for all } (x, y) \in \mathcal{X}\times \mathcal{Y},
    \label{def:information_density}
\end{equation}
where $Q$ is the {\em unique} capacity-achieving output distribution, given by $Q(y) = \frac{1}{|\mathcal{X}|}\sum_{z\in \mathcal{X}}W(y\mid z)$.

For any symmetric {\em singular} channel ${W \in \mathcal{P}(\mathcal{Y}\mid \mathcal{X})}$, the information density depends only on the output $Y$; that is,
    \begin{equation*}
        i(x, y) = \mathbb{E}[i(X,Y)\mid Y=y],
    \end{equation*}
    for all $(x,y) \in \mathcal{X}\times \mathcal{Y}$.
    Moreover, it takes the explicit form
    \begin{equation}
        i(x,y)=\begin{cases}
            \log\frac{|\mathcal{X}|}{|\mathcal{X}(y)|}, & \text{if } W(y\mid x)>0, \\
            -\infty, & \text{otherwise}.
         \end{cases}
        \label{eq:singular_info_density}
    \end{equation}

\label{lemma:ub_max_info}
    Let $W \in \mathcal{P}(\mathcal{Y}\mid \mathcal{X})$. The channel max-information is bounded  above as
    \begin{equation}
        I_{\max}(W) \leq \log \sum_{y \in \mathcal{Y}}\max_{x\in \mathcal{X}} W(y\mid x).
        \label{eq:ub_max_channel_info}
    \end{equation}

Define $q_m(y) := \frac{1}{c}\max_{x \in \mathcal{X}}W(y\mid x)$, where $c := \sum_{z\in \mathcal{Y}}\max_{x\in \mathcal{X}}W(z\mid x)$ is the normalisation constant. 
    Fix an arbitrary input distribution $p\in \mathcal{P}(\mathcal{X})$. By evaluating the inner infimum in the definition of the channel max-information in~\eqref{eq:ImaxW}
    at the specific distribution $q_m$, we obtain the upper bound
    \begin{align*}
        \inf_{q \in \mathcal{P}(\mathcal{Y})} D_{\max}(p\cdot W \,\|\, p\times q) &\leq D_{\max}(p\cdot W \,\|\, p\times q_m) \\
        &= \inf \left\{\lambda\in \mathbb{R}: p(x)W(y\mid x) \leq e^\lambda p(x)q_m(y), \forall (x,y) \right\}\\
        &= \inf \left\{\lambda\in \mathbb{R}: p(x)W(y\mid x) \leq \frac{e^\lambda}{c} p(x) \max_{x' \in \mathcal{X}} W(y\mid x'), \forall (x,y) \right\}\\
        &\leq \log c,
    \end{align*}
    where the final inequality holds because the condition is satisfied for all $(x,y)$ whenever $\frac{e^\lambda}{c} \geq 1$. Since this bound of $\log c$ depends only on the channel $W$ and holds simultaneously for all input distributions $p \in \mathcal{P}(\mathcal{X})$, taking the supremum over $p$ completes the proof.

\label{cor}
The $\epsilon$-smooth channel max-information is bounded  above as 
    \begin{equation}
 I^\epsilon_{\max}(W) \leq \log \inf_{\substack{\tilde{W}: \Delta(\tilde{W}, W) \leq \epsilon}}\sum_{y \in \mathcal{Y}}\max_{x\in \mathcal{X}} \tilde{W}(y\mid x).
        \label{eq:ub_epsilon_max_info}
    \end{equation}

\label{def:L_quantity}
    For a given channel $W \in \mathcal{P}(\mathcal{Y}\mid \mathcal{X})$, let
    \begin{equation}
        L^\epsilon(W) := \inf_{\substack{\tilde{W}\in \mathcal{P}(\mathcal{Y}\mid \mathcal{X}) : \Delta(\tilde{W}, W) \leq \epsilon}} \sum_{y \in \mathcal{Y}}\max_{x\in \mathcal{X}} \tilde{W}(y\mid x).
        \label{eq:Ldef}
    \end{equation}

\label{lemma:one_shot_ub_general}
    Let $W\in \mathcal{P}(\mathcal{Y}\mid \mathcal{X})$ be a symmetric channel and fix $\epsilon \in (0,1)$. The quantity $L^\epsilon(W)$ defined in Definition~\ref{def:L_quantity} is bounded above as,
    \begin{equation}
        \label{eq:one_shot_ub_general}
        L^\epsilon(W) \leq \inf_{\substack{\gamma \geq -\log r : \\ \mathbb{P}_{W_{x_0}}\left(i(x_0, Y) \geq \gamma\right) \leq \epsilon}} e^\gamma \quad \text{for any arbitrarily chosen } x_0 \in \mathcal{X},
    \end{equation}
    where $r = Q(\mathcal{Y}(x_0))$ and $Q(y) = \frac{1}{|\mathcal{X}|}\sum_{x \in \mathcal{X}}W(y\mid x)$ is the optimal capacity-achieving distribution.

We consider the family of conditional p.m.f.s
    \begin{equation}
        \label{def:W_proposal_general}
        \tilde{W}(y\mid x) := \frac{1}{c(M, x)} \min\{W(y\mid x), M Q(y)\}, \quad  (x, y) \in \mathcal{X}\times \mathcal{Y},
    \end{equation}
    where $M > 0$ is a tunable parameter, $Q(y) = \frac{1}{|\mathcal{X}|}\sum_{x\in \mathcal{X}}W(y\mid x)$ is the capacity-achieving output p.m.f.\ for the 
    symmetric channel $W$, and $c(M, x)$

    is the normalising factor. It is bounded from above as follows

    \begin{equation}
        c(M, x) = \sum_{y \in \mathcal{Y}} \min \{ W(y\mid x), MQ(y)\} = \sum_{y \in \mathcal{Y}(x)} \min \{ W(y\mid x), MQ(y)\} \leq M Q\left(\mathcal{Y}(x)\right) =: Mr(x),
    \end{equation}
where $\mathcal{Y}(x)$ is support set of $W_x$. By Lemma~\ref{lemma:c_independence_general}, both  $c(M, x)$ and $r(x)$ are independent of the input symbol $x$; thus, we denote $c(M, x)$  simply as $c(M)$ and $r(x)$ as $r$
    \begin{equation}
    \label{eq:c(M)_general}
        c(M) := \sum_{y\in \mathcal{Y} }\min\{W(y\mid x), M Q(y)\} \leq \min \{Mr, 1\}.
    \end{equation}

    Due to the symmetry of the channel, the worst-case TV distance between $\tilde{W}$ and $W$ is independent of the input $x \in \mathcal{X}$. We can bound it as,
    \begin{align}
        \Delta(\tilde{W}, W) &= \max_{x\in \mathcal{X}} \|\tilde{W}_x - W_x \|_{\mathrm{TV}} = \|\tilde{W}_{x_0} - W_{x_0}\|_{\mathrm{TV}}, \quad \text{for any } x_0 \in \mathcal{X} \nonumber\\
        &= \sum_{y\in \mathcal{Y}} \left(W(y\mid x_0) - \tilde{W}(y\mid x_0)\right) \mathbb{I}\left\{ W(y\mid x_0) \geq \tilde{W}(y\mid x_0) \right\} \nonumber\\
        &= \sum_{y\in \mathcal{Y}} \left(W(y\mid x_0) - \tilde{W}(y\mid x_0)\right) \mathbb{I}\left\{ W(y\mid x_0) \geq \frac{1}{c(M)} \min\{W(y\mid x_0), M Q(y)\} \right\} \nonumber\\
        &\leq \sum_{y\in \mathcal{Y}} W(y\mid x_0) \mathbb{I}\left\{ W(y\mid x_0) \geq \frac{M}{c(M)} Q(y) \right\} \label{eq:one_shot_general_costraint_step1}\\
        &= \mathbb{P}_{W_{x_0}}\left( W(Y\mid x_0) \geq \frac{M}{c(M)} Q(Y) \right), \nonumber
    \end{align}
    where~\eqref{eq:one_shot_general_costraint_step1} follows by considering the strictly positive contributions to the TV sum. If $W(y\mid x_0)\leq MQ(y)$, then $\tilde{W}(y\mid x_0)=W(y\mid x_0)/c(M)\geq W(y\mid x_0)$, so the contribution is zero. Otherwise, $\tilde{W}(y\mid x_0)=MQ(y)/c(M)$, and a strictly positive contribution requires $W(y\mid x_0)>MQ(y)/c(M)$. Bounding each such contribution by \(W(y\mid x_0)\) gives~\eqref{eq:one_shot_general_costraint_step1}.


    Then, rearranging the terms inside the probability and defining $\gamma(M) := \log \frac{M}{c(M)}$, we obtain
    \begin{equation}
        \label{eq:ub_general_constraint}
        \Delta(\tilde{W}, W) \leq \mathbb{P}_{W_{x_0}}\left( i(x_0, Y) \geq \gamma(M) \right).
    \end{equation}

    Next, evaluating the objective function $L^\epsilon(W)$ for the proposed $\tilde{W}$, gives
    \begin{align}
        \sum_{y\in \mathcal{Y}} \max_{x\in \mathcal{X}} \tilde{W}(y\mid x) &= \frac{1}{c(M)}\sum_{y\in \mathcal{Y}} \max_{x\in \mathcal{X}}\min \{ W(y\mid x), M Q(y)\} \nonumber\\
        &\leq \frac{1}{c(M)}\sum_{y\in \mathcal{Y}} \max_{x\in \mathcal{X}} M Q(y) = \frac{M}{c(M)} = e^{\gamma(M)}, \label{eq:ub_general_obj}
    \end{align}
    where the equality in the second line holds because $\sum_{y\in \mathcal{Y}} Q(y)=1$ and $Q(y)$ is independent of $x$. Therefore, combining the choice of $\tilde{W}$ from~\eqref{def:W_proposal_general} with the bounds in \eqref{eq:ub_general_constraint} and~\eqref{eq:ub_general_obj}, we deduce that for any $M$ satisfying $\mathbb{P}_{W_{x_0}}( i(x_0, Y) \geq \gamma(M) ) \leq \epsilon$, we have $\Delta(\tilde{W}, W) \leq \epsilon$. 

    For $S=\mathcal{Y}(x_0)$, let
$$
a=\min_{y\in S}\frac{W(y\mid x_0)}{Q(y)}>0,
\qquad
b=\max_{y\in S}\frac{W(y\mid x_0)}{Q(y)}<\infty.
$$
Since $Q(y)>0$ for any $y \in \mathcal{Y}$ ($W$ does not contain any all-zero columns), $c(M)$ from \eqref{eq:c(M)_general} can be expressed as

$$c(M) = \sum_{y\in \mathcal{Y}}Q(y)\min\left\{M, \frac{W(y\mid x)}{Q(y)}\right\}.$$

Then, $c(M)=Mr$ for $0<M\leq a$, and $c(M)=1$ for $M\geq b$.
Since $c(M)$ is positive and continuous, $M/c(M)$ is continuous, it equals $1/r$ for sufficiently small $M$, and tends to infinity as $M \to \infty$. Together with $M/c(M)\geq 1/r$, this implies that
$$
\{\gamma(M):M>0\}=[-\log r,\infty).$$
Finally, optimising over all valid $\gamma(M) \geq -\log r$ yields
    \begin{equation*}
        L^\epsilon(W) \leq \inf_{\substack{\gamma(M) \geq - \log r : \\ \mathbb{P}_{W_{x_0}}\left(i(x_0, Y) \geq \gamma(M) \right) \leq \epsilon}} e^{\gamma(M)},
    \end{equation*}
    for any arbitrarily chosen $x_0 \in \mathcal{X}$.

\label{thm:ub_general}
    Let $\epsilon \in (0,1)$ and $W\in \mathcal{P}(\mathcal{Y}\mid \mathcal{X})$ be a symmetric channel with $V(W) >0$. The $\epsilon$-smooth channel max-information of the memoryless channel $W^{\otimes n}$ is bounded  above as $n \to \infty$
    \begin{equation}
        \label{eq:general_ub}
        I_{\max}^\epsilon(W^{\otimes n}) \leq nC(W) + \sqrt{nV(W)}\Phi^{-1}\left(1-\epsilon +\frac{B(W)}{\sqrt{n}}\right),
    \end{equation}
    where $B(W)$ is a channel-dependent constant determined by the Berry--Esseen bound.

Since a product of symmetric channels results in a symmetric channel,  the one-shot result of Lemma~\ref{lemma:one_shot_ub_general} applied to $W^{\otimes n}$ gives
    \begin{equation}
        \label{eq:ub_L_n_general}
        L(W^{\otimes n}) \leq \inf_{\substack{\gamma_n \geq -\log r_n : \\ \mathbb{P}_{W_{x^n}}(i(x^n, Y^n)\geq \gamma_n) \leq \epsilon }} e^{\gamma_n}, \quad \text{for any arbitrary } x^n \in \mathcal{X}^n,
    \end{equation}
    where $r_n= Q^n(\mathcal{Y}^n(x^n)) = \prod_{i=1}^n Q(\mathcal{Y}(x_i))$. Following the result of Lemma \ref{lemma:c_independence_general}, $Q(\mathcal{Y}(x_i))$ is independent of $x_i$ implying that $r_n = r^n$, with $r: = Q(\mathcal{Y}(x_0))$ for some arbitrary $x_0\in \mathcal{X}$.

    Since the channel is memoryless, the information density tensorizes
    \begin{equation*}
        i(x^n, Y^n) = \log \frac{W^{\otimes n}(Y^n \mid x^n)}{Q^n(Y^n)} = \sum_{j=1}^n \log \frac{W(Y_j \mid x_j)}{Q(Y_j)} = \sum_{j=1}^n i(x_j, Y_j)
    \end{equation*}
    so that its mean is 
    \begin{align}
    \label{eq:mean_info_density_general}
        \mathbb{E}_{W_{x^n}}[i(x^n, Y^n)] = \sum_{j=1}^n \mathbb{E}_{W_{x_j}}[i(x_j, Y_j)]  = n \mathbb{E}_{W_{x_0}}[i(x_0, Y_0)], 
    \end{align}
    where the last step follows from the symmetry of the channel, ensuring that the expectation is independent of the input $x_j$ (evaluated at an arbitrary $x_0\in\mathcal{X}$). Similarly, the variance of the information density is
    \begin{equation}
        \label{eq:variance_info_density_general} 
        \mathrm{Var}_{W_{x^n}}[i(x^n, Y^n)] = \sum_{j=1}^n \mathrm{Var}_{W_{x_j}}[i(x_j, Y_j)] = n \mathrm{Var}_{W_{x_0}}[i(x_0, Y_0)].
    \end{equation}
    Using Lemma~\ref{lemma:capacity_dispersion} for~\eqref{eq:mean_info_density_general} and~\eqref{eq:variance_info_density_general}, we have
    \begin{equation}
        \label{eq:mean_variance_general} 
        \mathbb{E}_{W_{x^n}}[i(x^n, Y^n)] = nC(W) \quad \text{and} \quad \mathrm{Var}_{W_{x^n}}[i(x^n, Y^n)] = nV(W).
    \end{equation}
    Next, we choose the threshold $\gamma_n$ as
    \begin{equation}
        \label{eq:gamma_general}
        \gamma_n = nC(W) + \sqrt{nV(W)}\Phi^{-1}\left(1-\epsilon+ \frac{B(W)}{\sqrt{n}}\right),
    \end{equation}
    where $B(W)$ is the appropriate Berry--Esseen constant for the information density random variable.
    Note that for $n$ large enough, $\gamma_n$ is always well defined; i.e. $\gamma_n > 0$ and $1-\epsilon+\frac{B(W)}{\sqrt{n}} <1$.

     Following the results of Lemmas \ref{lemma:capacity_dispersion} and \ref{lemma:capacity_ineq_for_general}, for any $x_0 \in \mathcal{X}$, $C(W) = D(W_{x_0}\|Q) > -\log r $, implying that for any $n$ large enough such that
    $$\sqrt{\frac{V(W)}{n}}\Phi^{-1}\left(1-\epsilon+ \frac{B(W)}{\sqrt{n}}\right)\geq -\log r - C(W),$$
the choice for $\gamma_n$ is admissible for Lemma \ref{lemma:one_shot_ub_general}: $\gamma_n \geq -n\log r = -\log r_n$. Next, we can bound
    \begin{align}
        \mathbb{P}_{W_{x^n}}(i(x^n, Y^n)\geq \gamma_n) &= \mathbb{P}_{W_{x^n}}\left(\frac{\sum_{j=1}^n i(x_j, Y_j) - n C(W)}{\sqrt{nV(W)}} \geq \frac{\gamma_n - nC(W)}{\sqrt{nV(W)}} \right) \nonumber\\
        &= 1 - \mathbb{P}_{W_{x^n}}\left(\frac{\sum_{j=1}^n i(x_j, Y_j) - n C(W)}{\sqrt{nV(W)}} < \frac{\gamma_n - nC(W)}{\sqrt{nV(W)}} \right) \nonumber\\
        &\leq 1 - \Phi\left(\frac{\gamma_n - nC(W)}{\sqrt{nV(W)}} \right) + \frac{B(W)}{\sqrt{n}} \label{eq:berry_general_step2}\\
        &= 1 - \left(1-\epsilon +\frac{B(W)}{\sqrt{n}}\right) +\frac{B(W)}{\sqrt{n}} = \epsilon, \label{eq:berry_general_step3}
    \end{align}
    where~\eqref{eq:berry_general_step2} follows from the Berry--Esseen theorem \cite{petrov-book:95}, and~\eqref{eq:berry_general_step3} is obtained by substituting the value $\gamma_n$ from~\eqref{eq:gamma_general}. Because this choice of $\gamma_n$ satisfies asymptotically the constraint of the optimization problem in~\eqref{eq:ub_L_n_general} , we obtain $L(W^{\otimes n}) \leq e^{\gamma_n}$ for $n \to \infty$. 

    Taking the logarithm and applying the bound $I_{\max}^\epsilon(W^{\otimes n}) \leq \log L(W^{\otimes n})$ established in~\eqref{eq:ub_epsilon_max_info}, we obtain the desired result.

\label{thm:lb_ub_general}
     Let $\epsilon \in (0,1)$ and $W\in \mathcal{P}(\mathcal{Y}\mid \mathcal{X})$ be a symmetric {\em nonsingular} channel. The minimal simulation codebook size with fixed TV distance tolerance $\epsilon$, $M_\epsilon^*(W^{\otimes n})$, satisfies, as $n\to\infty$,
    \begin{equation}
        \label{eq:lb_ub_general}
        \log M_\epsilon^*(W^{\otimes n}) = nC(W) + \sqrt{n V(W)} \Phi^{-1}(1-\epsilon) + O(\log\log n).
    \end{equation}

\label{lemma:one_shot_ub_singular}
    Let $W \in \mathcal{P}(\mathcal{Y}\mid \mathcal{X})$ be a {\em singular} symmetric channel. For any $\epsilon\in (0,1)$ and any arbitrarly chosen $x_0 \in \mathcal{X}$, the quantity $L^\epsilon(W)$ defined in Definition~\ref{def:L_quantity} is bounded  above as 
    \begin{equation}
    \label{eq:ub_one_shot_singular}
        L^\epsilon(W) \leq \inf_{\substack{\gamma \in\mathbb R: \\ \mathbb{P}_{W_{x_0}}\left(i(x_0, Y) \geq \gamma\right) \leq \epsilon}} \frac{1}{1-\epsilon} \mathbb{E}_{W_{x_0}}\left[e^{i(x_0, Y)}\mathbb{I}\left\{i(x_0, Y) < \gamma\right\}\right], \quad \text{with } Y\sim W_{x_0}.
    \end{equation}

Let $\gamma \in \mathbb{R}$ be chosen such that

    \begin{equation}
    \label{eq:choice_gamma_singular}
        \mathbb P_{W_{x_0}}(i(x_0,Y)\ge\gamma) \leq \epsilon, \quad \text{with } Y \sim W_{x_0},
    \end{equation}
    for some arbitrary input symbol $x_0\in \mathcal{X}$.
Now consider the family of conditional distributions,
    \begin{equation}
        \label{def:sampled_distr_singular}
        \tilde{W}(y\mid x) := \frac{1}{c(x)} W(y\mid x)\mathbb{I}\{i(x, y) < \gamma\},
    \end{equation}
    where $c(x) := \sum_{y\in \mathcal{Y}}W(y\mid x) \mathbb{I}\{i(x, y) < \gamma\} \leq 1$ is the normalisation constant. Recall that, for a singular channel, the information density is $i(x,y) = \log \frac{|\mathcal{X}|}{|\mathcal{X}(y)|}$ whenever $W(y\mid x) > 0$~\eqref{eq:singular_info_density}. Consequently, $c(x)$ takes the form
    \begin{equation*}
        c(x) = \sum_{y\in \mathcal{Y}}W(y\mid x) \mathbb{I}\left\{\log \frac{|\mathcal{X}|}{|\mathcal{X}(y)|} < \gamma\right\}.
    \end{equation*}
    By~\eqref{eq:c2_constant} proved in Lemma~\ref{lemma:c_independence_general}, this sum is independent of the input $x$, so we simply denote it by $c$. We note that by the choice of $\gamma$ in \eqref{eq:choice_gamma_singular}, $\tilde{W}$ is always well defined because
    \begin{equation}
    \label{eq:lb_c_singular}
    c=\mathbb P_{W_{x_0}}(i(x_0,Y)<\gamma)
  =1-\mathbb P_{W_{x_0}}(i(x_0,Y)\ge\gamma)
  \ge1-\epsilon>0.
  \end{equation}

    Due to the symmetry of the channel, the worst-case TV distance between $\tilde{W}$ and $W$ is independent of the input $x \in \mathcal{X}$, and we can bound it above as follows
    \begin{align}
        \Delta(\tilde{W}, W) &= \max_{x\in \mathcal{X}}\|\tilde{W}_x - W_x \|_{\mathrm{TV}} = \|\tilde{W}_{x_0} - W_{x_0}\|_{\mathrm{TV}} \nonumber\\
        &= \sum_{y\in \mathcal{Y}} \left(W(y\mid x_0) - \tilde{W}(y\mid x_0)\right) \mathbb{I}\left\{W(y\mid x_0) \geq \tilde{W}(y\mid x_0)\right\} \nonumber\\
        &= \sum_{y\in \mathcal{Y}} \left(W(y\mid x_0) - \tilde{W}(y\mid x_0)\right) \mathbb{I}\left\{W(y\mid x_0) \geq \frac{1}{c} W(y\mid x_0)\mathbb{I}\{i(x_0, y) < \gamma\}\right\} \nonumber\\
        &= \sum_{y\in \mathcal{Y}} W(y\mid x_0) \mathbb{I}\left\{i(x_0, y) \geq \gamma\right\} \label{eq:one_shot_singular_costraint_step1}\\
        &= \mathbb{P}_{W_{x_0}}\left(i(x_0, Y) \geq \gamma\right), \label{eq:one_shot_singular_costraint}
    \end{align}
    where~\eqref{eq:one_shot_singular_costraint_step1} holds 
     because outputs satisfying $i(x_0,y)<\gamma$ have $\tilde{W}(y\mid x_0)=W(y\mid x_0)/c\geq W(y\mid x_0)$, and hence contribute zero to the TV sum. Outputs satisfying $i(x_0,y)\geq\gamma$ have $\tilde{W}(y\mid x_0)=0$, and hence contribute $W(y\mid x_0)$. Consequently, the TV distance equals the total probability of the latter region.



    Next, we evaluate the objective function for $L^\epsilon(W)$. For a singular channel, if $W(y\mid x) > 0$, it equals a constant $w(y)$ for all valid inputs, and the information density $i(x,y)$ depends only on $y$. Therefore,
    \begin{align}
        \sum_{y\in \mathcal{Y}} \max_{x\in \mathcal{X}} \tilde{W}(y\mid x) &= \sum_{y\in \mathcal{Y}} \max_{x\in \mathcal{X}} \frac{1}{c} W(y\mid x)\mathbb{I}\{i(x, y) < \gamma\} \nonumber\\
        &= \frac{1}{c} \sum_{y\in \mathcal{Y}} w(y)\mathbb{I}\left\{\log \frac{|\mathcal{X}|}{|\mathcal{X}(y)|} < \gamma\right\} \label{eq:obj_singular_step1}\\
        &= \frac{1}{c} \sum_{y\in \mathcal{Y}} Q(y)\frac{|\mathcal{X}|}{|\mathcal{X}(y)|}\mathbb{I}\left\{\log \frac{|\mathcal{X}|}{|\mathcal{X}(y)|} < \gamma\right\}, \label{eq:obj_singular_step1_5}
    \end{align}
    where~\eqref{eq:obj_singular_step1_5} follows from the singular channel property $w(y) = Q(y) \frac{|\mathcal{X}|}{|\mathcal{X}(y)|}$. Expanding the capacity-achieving output distribution $Q(y) = \frac{1}{|\mathcal{X}|}\sum_{x\in \mathcal{X}}W(y\mid x)$, we obtain
    \begin{align}
        \sum_{y\in \mathcal{Y}} \max_{x\in \mathcal{X}} \tilde{W}(y\mid x) &= \frac{1}{c} \sum_{x\in \mathcal{X}} \sum_{y\in \mathcal{Y}} \frac{1}{|\mathcal{X}|}W(y\mid x) \frac{|\mathcal{X}|}{|\mathcal{X}(y)|}\mathbb{I}\left\{\log \frac{|\mathcal{X}|}{|\mathcal{X}(y)|} < \gamma\right\} \label{eq:obj_singular_step2} \\
        &= \frac{1}{c} \sum_{x\in \mathcal{X}} \frac{1}{|\mathcal{X}|} \left(\sum_{y\in \mathcal{Y}} W(y\mid x) e^{i(x, y)}\mathbb{I}\left\{i(x, y) < \gamma\right\} \right) \nonumber\\
        &= \frac{1}{c} \sum_{y\in \mathcal{Y}} W(y\mid x_0) e^{i(x_0, y)}\mathbb{I}\left\{i(x_0, y) < \gamma\right\} \sum_{x\in \mathcal{X}} \frac{1}{|\mathcal{X}|} \label{eq:obj_singular_step3}\\
        &= \frac{1}{c}\mathbb{E}_{W_{x_0}} \left[e^{i(x_0, Y)}\mathbb{I}\left\{ i(x_0, Y) < \gamma\right\} \right], \label{eq:obj_singular_step4}
    \end{align}
    where~\eqref{eq:obj_singular_step3} follows from~\eqref{eq:c3_constant} in  Lemma~\ref{lemma:c_independence_general} in the Appendix, allowing us to replace the inner sum with its value at an arbitrary $x_0 \in \mathcal{X}$. Substituting the lower bound for $c$ from \eqref{eq:lb_c_singular}   into~\eqref{eq:obj_singular_step4} yields
    \begin{equation*}
        \sum_{y\in \mathcal{Y}} \max_{x\in \mathcal{X}} \tilde{W}(y\mid x) \leq \frac{1}{1-\epsilon}\mathbb{E}_{W_{x_0}} \left[e^{i(x_0, Y)}\mathbb{I}\left\{ i(x_0, Y) < \gamma\right\} \right].
    \end{equation*}
    Taking the infimum over all valid thresholds $\gamma$  from \eqref{eq:choice_gamma_singular} yields the desired upper bound on $L^\epsilon(W)$.

\label{thm:ub_singular}
         Let $\epsilon \in (0,1)$ and $W\in \mathcal{P}(\mathcal{Y}\mid \mathcal{X})$ be a symmetric {\em singular} channel with $V(W)>0$. 
         Let $B(W)$ be the Berry--Esseen constant used in Theorem~\ref{thm:ub_general}, 
        and define
        $$
        T(W):=\mathbb E_{W_{x_0}}
        |i(x_0,Y)-C(W)|^3,
        \qquad
        A(W):=
        \frac1{\sqrt{2\pi V(W)}}
        +\frac{2T(W)}{V(W)^{3/2}},
       $$
       for any $x_0\in{\cal X}$.
         Then, the $\epsilon$-smooth channel max-information of the memoryless channel $W^{\otimes n}$ satisfies, for all $n>(B(W)/\epsilon)^2$,
    \begin{equation}
        \label{eq:singular_ub}
        I_{\max}^\epsilon(W^{\otimes n}) \leq nC(W) + \sqrt{nV(W)}\Phi^{-1}\left(1-\epsilon +\frac{B(W)}{\sqrt{n}}\right) - \frac{1}{2}\log n + \log\Big(\frac{A(W)}{1-\epsilon}\Big). 
    \end{equation}

Lemma~\ref{lemma:one_shot_ub_singular} applied to  $W^{\otimes n}$ states that
    \begin{equation}
        \label{eq:ub_L_n_singular1}
        L(W^{\otimes n}) \leq \inf_{\substack{\gamma_n \in \mathbb{R} : \\ \mathbb{P}_{W_{x^n}}(i(x^n, Y^n) \geq \gamma_n)\leq \epsilon}} \frac{1}{1-\epsilon} \mathbb{E}_{W_{x^n}}\left[e^{i(x^n, Y^n)}\mathbb{I}\left\{i(x^n, Y^n) < \gamma_n\right\}\right],
    \end{equation}
    for any $x^n \in \mathcal{X}^n$. 
    As in the part of the proof of Theorem~\ref{thm:ub_general} leading 
    to~\eqref{eq:mean_variance_general}, since the information density $i(x^n, Y^n)$ tensorizes, its mean and variance are given by
    \begin{equation}
    \label{eq:mean_variance_singular}
        \mathbb{E}_{W_{x^n}}[i(x^n, Y^n)] = nC(W) \quad \text{and} \quad \mathrm{Var}_{W_{x^n}}[i(x^n, Y^n)] = nV(W).
    \end{equation}

    We choose the threshold $\gamma_n$ as in~\eqref{eq:gamma_general},
    \begin{equation}
        \label{eq:gamma_singular}
        \gamma_n = nC(W) + \sqrt{nV(W)}\Phi^{-1}\left(1-\epsilon+ \frac{B(W)}{\sqrt{n}}\right),
    \end{equation}
    where $B(W)$ is the Berry--Esseen constant. 
    For $n>(B(W)/\epsilon)^2$,  we have that $1-\epsilon+B(W)/\sqrt n$ belongs in $(0,1)$, so $\gamma_n$ is finite.

    With this choice for $\gamma_n$, the tail probability constraint is  satisfied
    \begin{align}
        \mathbb{P}_{W_{x^n}}(i(x^n, Y^n) \geq \gamma_n) &= \mathbb{P}_{W_{x^n}}\left(\frac{\sum_{j=1}^n i(x_j, Y_j) - n C(W)}{\sqrt{nV(W)}} \geq \frac{\gamma_n - nC(W)}{\sqrt{nV(W)}} \right) \nonumber\\
        &= 1 - \mathbb{P}_{W_{x^n}}\left(\frac{\sum_{j=1}^n i(x_j, Y_j) - n C(W)}{\sqrt{nV(W)}} < \frac{\gamma_n - nC(W)}{\sqrt{nV(W)}} \right) \nonumber\\
        &\leq 1 - \Phi\left(\frac{\gamma_n - nC(W)}{\sqrt{nV(W)}} \right) + \frac{B(W)}{\sqrt{n}} \label{eq:berry_singular_step2}\\
        &= 1 - \left(1-\epsilon +\frac{B(W)}{\sqrt{n}}\right) +\frac{B(W)}{\sqrt{n}} = \epsilon, \label{eq:berry_singular_step3}
    \end{align}
    where~\eqref{eq:berry_singular_step2} follows from the Berry--Esseen theorem, and~\eqref{eq:berry_singular_step3} is obtained by substituting our choice of $\gamma_n$ from~\eqref{eq:gamma_singular}. After rearranging and using the tensorization property, the objective in~\eqref{eq:ub_L_n_singular1} can be bounded from above using~\cite[Lemma~2]{altug_wagner_symmetric_channels} as,
    \begin{align}
        \frac{1}{1-\epsilon} \mathbb{E}_{W_{x^n}}\left[e^{i(x^n, Y^n)}\mathbb{I}\left\{i(x^n, Y^n) < \gamma_n\right\}\right] &= \frac{1}{1-\epsilon} \mathbb{E}_{W_{x^n}}\left[e^{\sum_{j=1}^n i(x_j, Y_j)}\mathbb{I}\left\{\sum_{j=1}^n i(x_j, Y_j) < \gamma_n\right\}\right] \nonumber\\
        &\leq \frac{1}{1-\epsilon}\cdot \frac{e^{\gamma_n}}{\sqrt{n}}\left(\frac{1}{\sqrt{2\pi V(W)}} + \frac{2T(W)}{V(W)^{3/2}}\right).
        \label{eq:tocombine}
    \end{align}
    Then, combining~\eqref{eq:ub_L_n_singular1} and~\eqref{eq:tocombine} gives,
$$
L(W^{\otimes n})
\leq
\frac{A(W)}{1-\epsilon}\,
\frac{e^{\gamma_n}}{\sqrt n},
$$
and taking logarithms and applying Corollary~\ref{cor} we get
$$
I_{\max}^{\epsilon}(W^{\otimes n})
\le
\gamma_n-\frac{1}{2}\log n
+\log\left(\frac{A(W)}{1-\epsilon}\right).
$$
Substituting the value of $\gamma_n$  proves the stated bound.

Let $\epsilon \in (0,1)$ and $W\in \mathcal{P}(\mathcal{Y}\mid \mathcal{X})$ be a symmetric {\em singular} channel with $V(W) >0$. The minimal simulation codebook size $M_\epsilon^*(W^{\otimes n})$ with fixed TV distance tolerance $\epsilon$ satisfies, as $n\to\infty$,
    \begin{equation}
        \label{eq:lb_ub_singular}
        \log M_\epsilon^*(W^{\otimes n}) = nC(W) + \sqrt{n V(W)} \Phi^{-1}(1-\epsilon) - \frac{1}{2}\log n + O(\log\log n).
    \end{equation}

We begin with the lower bound. Arguing exactly as in the proof of Theorem~\ref{thm:lb_ub_general} up to the point leading to~\eqref{eq:toreuse}, and taking $b(W)=0$ this time,  we obtain,
    in the notation of that proof,
    \begin{equation}
  \log M_\epsilon^*(W^{\otimes n})
  \geq G_\epsilon(n)-\frac{1}{2}\log n-K_-.
  \label{eq:lb_M_singular}
    \end{equation}











    For the upper bound, we apply~\cite[Theorem~2]{Cao_channel_simulation},
    \begin{equation*}
        \log M_\epsilon^*(W^{\otimes n}) \leq I_{\max}^{\epsilon-\delta}(W^{\otimes n}) + \log\log \frac{1}{\delta},
    \end{equation*}
    which holds for any $\delta \in (0, \epsilon)$. 


With $\eta_n$ and $\gamma_n^*$ as in the proof of Theorem~\ref{thm:lb_ub_general}, we have
\begin{align*}
I_{\max}^{\eta_n}(W^{\otimes n})
&\leq \gamma_n^*-\frac{1}{2}\log n
    +\log\frac{A(W)}{1-\eta_n}\\
&=\gamma_n^*-\frac12\log n
    +\log\frac{A(W)}{1-\epsilon+n^{-1/2}}\\
&\leq\gamma_n^*-\frac12\log n
    +\log\frac{A(W)}{1-\epsilon}.
\end{align*}    

    So now setting $\delta = \frac{1}{\sqrt{n}}$ for $n$ sufficiently large yields
    \begin{align}
        \log M_\epsilon^*(W^{\otimes n}) &\leq n C(W) + \sqrt{n V(W)}\Phi^{-1}\left(1-\epsilon+\frac{B(W)+1}{\sqrt{n}} \right) - \frac{1}{2}\log n + \log\log \sqrt{n}  \nonumber\\
        &\leq n C(W) + \sqrt{n V(W)}\Phi^{-1}\left(1-\epsilon \right) - \frac{1}{2}\log n + \log\log n +O(1), \label{eq:ub_M_singular}
    \end{align}
    where the last inequality again follows by a first-order Taylor expansion of $\Phi^{-1}$, and by absorbing the constant from $\log\log \sqrt{n}$ into the $O(1)$ term. Combining~\eqref{eq:lb_M_singular} and~\eqref{eq:ub_M_singular} completes the proof.

\label{lemma:c_independence_general}
    Let $W\in \mathcal{P}(\mathcal{Y}\mid \mathcal{X})$ be a symmetric channel and $\gamma>0$.
    Write
    $Q(y) = \frac{1}{|\mathcal{X}|}\sum_{x\in \mathcal{X}}W(y\mid x)$, $y\in\mathcal{Y}$. 
    The quantities
    \begin{align}
        c_1(x) &= \sum_{y \in \mathcal{Y}}\min\{W(y\mid x), \gamma Q(y)\}, \label{eq:c1_constant}\\
        c_2(x) &= \sum_{y\in \mathcal{Y}}W(y\mid x) \mathbb{I}\left\{\frac{|\mathcal{X}|}{|\mathcal{X}(y)|}\leq \gamma\right\}, \label{eq:c2_constant}\\
        c_3(x) &= \sum_{y\in \mathcal{Y}} W(y\mid x) \frac{|\mathcal{X}|}{|\mathcal{X}(y)|}\mathbb{I}\left\{ \frac{|\mathcal{X}|}{|\mathcal{X}(y)|}\leq \gamma\right\}, \label{eq:c3_constant}\\
        r(x) &= \sum_{y\in \mathcal{Y}(x)}Q(y), \label{eq:r_constant}
    \end{align}
    are all independent of $x$.

Since $W$ is symmetric, the output alphabet $\mathcal{Y}$ can be partitioned into disjoint subsets $\{\mathcal{Y}_1, \mathcal{Y}_2, \ldots, \mathcal{Y}_k\}$ such that, within each  $\mathcal{Y}_i$, the columns of the transition submatrix are permutations of one another. Therefore, 
    \begin{equation}
        Q(y_1) = \frac{1}{|\mathcal{X}|} \sum_{x\in \mathcal{X}}W(y_1\mid x) = \frac{1}{|\mathcal{X}|}\sum_{x\in \mathcal{X}}W(y_2\mid x) = Q(y_2), \quad \text{for any } y_1, y_2 \in \mathcal{Y}_i.
        \label{eq:constant_Q_proof}
    \end{equation}
    This implies that $Q$ is constant on each ${\cal Y}_i$; let $q_i$ denote this constant value. Then, for any $x_1, x_2 \in \mathcal{X}$,
    \begin{align*}
        c_1(x_1) &= \sum_{y\in \mathcal{Y}} \min\{W(y\mid x_1), \gamma Q(y)\} = \sum_{i=1}^k \sum_{y \in \mathcal{Y}_i} \min\{W(y\mid x_1), \gamma q_i\} \\
        &= \sum_{i=1}^k \sum_{y \in \mathcal{Y}_i} \min\{W(y\mid x_2), \gamma q_i\} = c_1(x_2),
    \end{align*}
    where the third equality follows because, within each subset $\mathcal{Y}_i$, the elements $\{W(y\mid x_1)\}_{y \in \mathcal{Y}_i}$ are a permutation of the elements $\{W(y\mid x_2)\}_{y \in \mathcal{Y}_i}$. 

    For $c_2(x)$ we have
    \begin{equation*}
        c_2(x) = \sum_{i=1}^k \sum_{y \in \mathcal{Y}_i} W(y\mid x) \mathbb{I}\left\{\frac{|\mathcal{X}|}{|\mathcal{X}(y)|}\leq \gamma\right\} = \sum_{i=1}^k I_i \sum_{y \in \mathcal{Y}_i} W(y\mid x),
    \end{equation*}
    where $I_i := \mathbb{I}\left\{ |\mathcal{X}|/|\mathcal{X}(y)| \leq \gamma \right\}$ is constant over $\mathcal{Y}_i$ because the columns of the submatrix are permutations (and therefore $|\mathcal{X}(y)|$ is constant for $y \in \mathcal{Y}_i$). Moreover, because the rows are permutation-invariant within each $\mathcal{Y}_i$, the sum $\sum_{y \in \mathcal{Y}_i} W(y\mid x)$ is also independent of $x$. This completes the proof for $c_2(x)$. The result for $c_3(x)$ follows along the same lines. 

    The independence of $r(x)$ can be argued as follows


    $$r(x) = \sum_{y \in \mathcal{Y}(x)} Q(y) = \sum_{i = 1}^k \sum_{y \in \mathcal{Y}(x)\cap \mathcal{Y}_i}Q(y) = \sum_{i = 1}^k |\mathcal{Y}(x)\cap \mathcal{Y}_i|q_i.$$

    For any $x_1\in \mathcal{X}$ and $x_2 \in \mathcal{X}$, the set of transition probabilities $\{W(y\mid x_1)\}_{y\in \mathcal{Y}_i}$ is a permutation of ${\{W(y\mid x_2)\}_{y\in \mathcal{Y}_i}}$ (row permutation). Therefore, the number of non-zero elements in $\mathcal{Y}(x)\cap \mathcal{Y}_i$ is independent of the input symbol, which combined with the expansion above of $r(x)$ gives the desired result.

\label{lemma:capacity_dispersion}
    Let $W \in \mathcal{P}(\mathcal{Y}\mid \mathcal{X})$ be a symmetric channel, $Q\in \mathcal{P}(\mathcal{Y})$ its capacity-achieving output p.m.f., and fix $\epsilon \in(0,1)$. The channel capacity, $C(W)$, and the channel dispersion, $V(W)$, can be expressed as:
    \begin{equation}
        C(W) = \mathbb{E}_{W_{x_0}}[i(x_0, Y)] \quad \text{and} \quad V_\epsilon(W) = \mathrm{Var}_{W_{x_0}}[i(x_0, Y)],
    \end{equation}
    for any arbitrarily chosen $x_0 \in \mathcal{X}$.

The result follows easily from the log-sum inequality:

\begin{align*}
    D(W_x\|Q) &= \sum_{y \in \mathcal{Y}}W_x(y)\log \frac{W_x(y)}{Q(y)} = \sum_{y \in \mathcal{Y}(x)}W_x(y)\log \frac{W_x(y)}{Q(y)}\\
    &\geq \left(\sum_{y \in \mathcal{Y}(x)}W_x(y)\right) \log\frac{\left(\sum_{y \in \mathcal{Y}(x)}W_x(y)\right)}{\left(\sum_{y \in \mathcal{Y}(x)}Q(y)\right)} = \log \frac{1}{\sum_{y\in \mathcal{Y}(x)}Q(y)} = - \log Q(\mathcal{Y}(x)).
\end{align*}
